const HaemanPhaseB={"cards":[{"name":"Windows Kernel Development","description":"Windows kernel components and device drivers for hardware integration, device communication, and system-level behavior.","cta":"Explore Windows Driver Development","href":"/services/windows-kernel/"},{"name":"Embedded Firmware and Embedded Linux","description":"Firmware for microcontrollers and devices running an RTOS. Embedded Linux development for board support, system images, and user-space integration.","cta":"Explore Embedded Engineering","href":"/services/embedded/"},{"name":"Linux Kernel and Systems Programming","description":"Linux kernel development for device interfaces and kernel-level behavior. C/C++ systems programming for the surrounding services and software components.","cta":"Discuss Your Project","href":"/contact/","capabilities":["Linux Kernel","C","C++","Device Interfaces","Systems Software"]}],"problems":[{"title":"Driver Crashes and Device Failures","description":"A driver crashes, a device disconnects, or an operation fails under load. Identify a reproducible failure and define how the underlying issue will be investigated.","link":"Windows driver debugging","href":"/services/windows-kernel/debugging-bsod/"},{"title":"Firmware and Hardware Bring-Up","description":"A board needs firmware before its peripherals and application behavior can be tested together. Define the hardware inputs, interfaces, and expected device behavior.","link":"Embedded firmware development","href":"/services/embedded/firmware-development/"},{"title":"Linux Kernel and Device Interfaces","description":"A device interface needs kernel-level development or investigation. Define the target hardware, kernel version, and expected behavior before deciding what changes are needed.","link":"Discuss Linux kernel requirements","href":"/contact/"},{"title":"C/C++ Component Integration","description":"Services and software components need a clear communication contract. Define data ownership, request handling, and failure behavior so the parts can be developed and tested together.","link":"C++ Windows development","href":"/services/windows-applications/native-cpp/"}],"principles":[{"title":"System Constraints","desc":"Understand the operating system, hardware, and expected behavior before defining the implementation."},{"title":"Clear Interfaces","desc":"Agree component responsibilities, communication contracts, and integration assumptions."},{"title":"Testable Requirements","desc":"Define how the delivered behavior will be checked, using software tests and hardware measurements where appropriate."},{"title":"Project Communication","desc":"Discuss technical decisions, dependencies, and unresolved questions at agreed review points."},{"title":"Practical Handover","desc":"Agree the source code, build, configuration, and test documentation deliverables, together with release and maintenance responsibilities."}],"disciplines":[{"year":"01","title":"Windows Kernel Development","desc":"Windows kernel components and device drivers for hardware integration, device communication, and operating system behavior.","link":"Windows driver development","href":"/services/windows-kernel/"},{"year":"02","title":"Linux Kernel Development","desc":"Linux kernel components and device driver interfaces, scoped to the target hardware, kernel version, and required kernel-level behavior.","link":"Discuss Linux kernel requirements","href":"/contact/"},{"year":"03","title":"Embedded Firmware","desc":"Firmware for microcontrollers and RTOS-based devices, covering peripheral communication, device behavior, and integration with the hardware.","link":"Embedded firmware development","href":"/services/embedded/firmware-development/"},{"year":"04","title":"Embedded Linux Development","desc":"Board support, system images, boot configuration, and user-space integration for devices running Linux. Any kernel changes are identified and scoped explicitly.","link":"Embedded Linux development","href":"/services/embedded/embedded-linux/"},{"year":"05","title":"C/C++ Systems Programming","desc":"C/C++ software for system interfaces, background components, and device communication. Windows application development complements this work when a desktop interface or control panel is needed.","link":"C++ Windows development","href":"/services/windows-applications/native-cpp/"}],"related":[{"text":"Embedded firmware","href":"/services/embedded/firmware-development/"},{"text":"Embedded Linux","href":"/services/embedded/embedded-linux/"},{"text":"Windows applications","href":"/services/windows-applications/"}]};
